function dir$dmnganhnghe(p){
  this.constructor(p);
}
dir$dmnganhnghe.prototype = new DirEvent();
dir$dmnganhnghe.prototype.afterInit = function(){
  var p = this._dir, g = p.grid();
  dir$dmnganhngheDisabledMasterField(p, g);
}
function dir$dmnganhngheDisabledMasterField(p, g){

  if(p.valForm('ma_nganhnghe').trim() != '')
  {
    p.setDisabled('ma_nganhnghe', true);
  }
  else
  {
    p.setDisabled('ma_nganhnghe', false);
  }
}






	.control-label.ma_nganhnghe, .control-label.ten_nganhnghe
	{	
		color: #499b98;;
	}








